arguments.command:
$PYTHON = ""
$GRAPHIFY_BIN = (Get-Command graphify -ErrorAction SilentlyContinue).Source
if (-not $PYTHON -and (Get-Command uv -ErrorAction SilentlyContinue)) {
    $_UV_PY = uv tool run --from graphifyy python -c "import sys; print(sys.executable)" 2>$null
    if ($_UV_PY) { $PYTHON = $_UV_PY.Trim() }
}
if (-not $PYTHON -and $GRAPHIFY_BIN) {
    $_SHEBANG = (Get-Content $GRAPHIFY_BIN -TotalCount 1) -replace '^#!', ''
    try {
        & $_SHEBANG -c "import graphify" 2>$null
        if ($?) { $PYTHON = $_SHEBANG }
    } catch {}
}
if (-not $PYTHON) { $PYTHON = "python" }
& $PYTHON -c "import graphify" 2>$null
if (-not $?) {
    if (Get-Command uv -ErrorAction SilentlyContinue) {
        uv tool install --upgrade graphifyy -q 2>&1 | Select-Object -Last 3
        $_UV_PY = uv tool run --from graphifyy python -c "import sys; print(sys.executable)" 2>$null
        if ($_UV_PY) { $PYTHON = $_UV_PY.Trim() }
    } else {
        & $PYTHON -m pip install graphifyy -q 2>$null
        if (-not $?) {
            & $PYTHON -m pip install graphifyy -q --break-system-packages 2>&1 | Select-Object -Last 3
        }
    }
}
New-Item -ItemType Directory -Force -Path "graphify-out" | Out-Null
& $PYTHON -c "import sys; open('graphify-out/.graphify_python', 'w', encoding='utf-8').write(sys.executable)"
$inputPathAbs = (Get-Item .).FullName
& $PYTHON -c "import os, sys; out_path = os.path.abspath('graphify-out/.graphify_root'); os.chdir(sys.stdin.readline().rstrip('\r\n')); open(out_path, 'w', encoding='utf-8').write(os.getcwd())" <<'GRAPHIFY_ROOT_EOF'
$inputPathAbs
GRAPHIFY_ROOT_EOF

